import numpy as np
from scipy.optimize import minimize
import random

def objective(p):
    x, y, z = p
    return -(x*y**3 + y*z**3 + z*x**3)

def constraint(p):
    return p[0]**2 + p[1]**2 + p[2]**2 - 3

cons = ({'type': 'eq', 'fun': constraint})

solutions = []
for _ in range(5000):
    phi = random.uniform(0, np.pi)
    theta = random.uniform(0, 2*np.pi)
    x = np.sqrt(3) * np.sin(phi) * np.cos(theta)
    y = np.sqrt(3) * np.sin(phi) * np.sin(theta)
    z = np.sqrt(3) * np.cos(phi)

    res = minimize(objective, [x, y, z], constraints=cons)
    if res.success:
        val = -res.fun
        if abs(val - 3.0) < 1e-4:
            is_new = True
            for sol in solutions:
                if np.allclose(res.x, sol, atol=1e-3):
                    is_new = False
                    break
            if is_new:
                solutions.append(res.x)

print(f"Total unique solutions found: {len(solutions)}")
for sol in solutions:
    print(sol)

